// streamVerifyObject reads the content object filed under digest once through
// a fixed-size buffer, requiring it to be a regular file (never a symlink or
// other special file) whose full bytes hash to digest, and confirms the size
// recorded for it by every referencing entry. It is the streaming counterpart
// of readVerifiedObject: it returns the object's true byte count but never the
// bytes themselves, so verification memory does not depend on object size. The
// error wording matches readHealthyObject/readVerifiedObject so callers and
// tests cannot distinguish the streaming path.
func (s *Store) streamVerifyObject(digest string, entries map[string]Entry) (int64, error) {
	path := s.objectPath(digest)
	info, err := os.Lstat(path)
	if err != nil {
		return 0, err
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return 0, errors.New("object path is a symbolic link")
	}
	if !info.Mode().IsRegular() {
		return 0, errors.New("object path is not a regular file")
	}
	file, err := os.Open(path)
	if err != nil {
		return 0, err
	}
	hash := sha256.New()
	buf := make([]byte, exportBufferSize)
	n, copyErr := io.CopyBuffer(hash, streamReader{file}, buf)
	closeErr := file.Close()
	if copyErr != nil {
		return 0, copyErr
	}
	if closeErr != nil {
		return 0, closeErr
	}
	if actual := hex.EncodeToString(hash.Sum(nil)); actual != digest {
		return 0, fmt.Errorf("content checksum is %s", actual)
	}
	// Every entry referencing this digest must agree on the size; a content
	// hash fixes the byte count, so a disagreement is a corrupt record.
	for _, entry := range entries {
		if entry.Digest == digest && n != entry.Size {
			return 0, fmt.Errorf("content is %d bytes, record for %q says %d", n, entry.Name, entry.Size)
		}
	}
	return n, nil
}

