53	// names, entries, and snapshot records stay resident, scaling with the number
54	// of records.
55	//
56	// The output location is held to the same rules as a download: it must be
57	// outside the source repository (judged on actual locations, through
58	// symlinks, and before the file exists), its parent directory must already
59	// exist, an existing output must be a regular file that is not hard-linked to
60	// any index, snapshot record, lock file, or content object, and the package
61	// is committed through a descriptor pinned to the resolved parent directory,
62	// so a parent swapped for a symlink into the repository while the export runs
63	// is detected at commit time and can never redirect the package onto a
64	// repository file. The package is written to a temporary file in that
65	// directory before an atomic rename: a failed export never creates or alters
66	// the output file.
67	func (s *Store) ExportSnapshot(name, base, output string) (ExportResult, error) {
68		if err := validateName(name); err != nil {
69			return ExportResult{}, err
70		}
71		if base != "" {
72			if err := validateName(base); err != nil {
73				return ExportResult{}, err
74			}
75		}
76		if output == "" {
77			return ExportResult{}, errors.New("output is required")
78		}
79		// Export reads an existing, initialized repository; it never creates one.
80		// The root and index are checked before taking the lock (withLockOpts
81		// passes createRoot=false so even the root directory is not materialized),
82		// and re-checked while holding the lock.
83		rootInfo, err := os.Stat(s.root)
84		switch {
85		case errors.Is(err, os.ErrNotExist):
86			return ExportResult{}, fmt.Errorf("repository %q does not exist; run init first", s.root)
87		case err != nil:
88			return ExportResult{}, err
89		case !rootInfo.IsDir():
90			return ExportResult{}, fmt.Errorf("repository root %q is not a directory", s.root)
91		}
92		if _, err := os.Stat(s.indexPath()); errors.Is(err, os.ErrNotExist) {
93			return ExportResult{}, fmt.Errorf("repository %q is not initialized; run init first", s.root)
94		} else if err != nil {
95			return ExportResult{}, err
96		}
97		var result ExportResult
98		err = s.withLockOpts(true, false, func() error {
99			if _, err := os.Stat(s.indexPath()); errors.Is(err, os.ErrNotExist) {
100				return fmt.Errorf("repository %q is not initialized; run init first", s.root)
101			} else if err != nil {
102				return err
103			}
104			// Validate the destination before reading any object or staging a
105			// temporary file, and hold the pinned parent directory until commit.
106			absOut, mode, pin, err := s.checkOutputSafe(output)
107			if err != nil {
108				return err
109			}
110			defer pin.Close()
111	
112			target, err := s.loadSnapshotRecord(name)
113			if err != nil {
114				return err
115			}
116			var baseSnap Snapshot
